import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js';

const mount=document.querySelector('#game');
const scene=new THREE.Scene(); scene.background=new THREE.Color(0x9ab8c5); scene.fog=new THREE.FogExp2(0x9ab8c5,.0125);
const camera=new THREE.PerspectiveCamera(48,innerWidth/innerHeight,.1,180);
const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false}); renderer.setPixelRatio(Math.min(devicePixelRatio,1.8)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.16; mount.appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight(0xdff4ff,0x354858,2.1));
const sun=new THREE.DirectionalLight(0xffe6c6,3.2); sun.position.set(-18,30,14);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-42;sun.shadow.camera.right=42;sun.shadow.camera.top=42;sun.shadow.camera.bottom=-42;sun.shadow.bias=-.0002;scene.add(sun);
const moon=new THREE.DirectionalLight(0x91c9ef,1.45);moon.position.set(20,12,-20);scene.add(moon);
const mat=(color,rough=.86,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const groundMat=mat(0xc8d7d9,.96), iceMat=mat(0x8bc4d1,.3,.2), darkMat=mat(0x263946), furMat=mat(0x463b39), skinMat=mat(0xc5a27f), goldMat=mat(0xc2a15c,.36,.7), woodMat=mat(0x553b2b), snowMat=mat(0xe4f0ed,.84), barkMat=mat(0x55453d), pineMat=mat(0x334c4c), pineLight=mat(0x496566), enemyMat=mat(0x566967), enemyDark=mat(0x263737), glowMat=new THREE.MeshBasicMaterial({color:0x9df0ff});
const box=(w,h,d,m)=>new THREE.Mesh(new THREE.BoxGeometry(w,h,d),m);
const sphere=(r,m,seg=12)=>new THREE.Mesh(new THREE.SphereGeometry(r,seg,Math.max(6,seg>>1)),m);
const cone=(r,h,m,n=7)=>new THREE.Mesh(new THREE.ConeGeometry(r,h,n),m);
function addMesh(parent,obj,x,y,z){obj.position.set(x,y,z);parent.add(obj);obj.castShadow=true;obj.receiveShadow=true;return obj}
// Vast frost plain, broken by a raised, cracked ice ring.
const ground=new THREE.Mesh(new THREE.PlaneGeometry(240,240),groundMat);ground.rotation.x=-Math.PI/2;ground.position.y=-.12;ground.receiveShadow=true;scene.add(ground);
const ring=new THREE.Mesh(new THREE.CylinderGeometry(11,12,.26,12,1,true),iceMat);ring.position.y=.02;ring.receiveShadow=true;scene.add(ring);
const platform=new THREE.Mesh(new THREE.CylinderGeometry(10.2,10.7,.18,12),snowMat);platform.position.y=.04;platform.receiveShadow=true;scene.add(platform);
// Scattered blue fissures catch the light beneath the snow.
for(let i=0;i<18;i++){const a=i*.83+Math.random()*.3,r=4+Math.random()*5;const crack=new THREE.Mesh(new THREE.BoxGeometry(.035,.025,1+Math.random()*2),new THREE.MeshBasicMaterial({color:0x9edce4,transparent:true,opacity:.36}));crack.position.set(Math.cos(a)*r,.145,Math.sin(a)*r);crack.rotation.y=a+.6;scene.add(crack)}
// Simple low-poly winter forest silhouettes.
for(let i=0;i<100;i++){const a=Math.random()*Math.PI*2,r=14+Math.random()*70,x=Math.cos(a)*r,z=Math.sin(a)*r;const h=2.3+Math.random()*4;const tree=new THREE.Group();tree.position.set(x,0,z);tree.rotation.y=Math.random()*Math.PI;const trunk=addMesh(tree,new THREE.CylinderGeometry(.13,.25,h*.36,6),0,h*.18,0);trunk.material=barkMat;for(let j=0;j<3;j++){const c=cone(1.05-j*.2,h*.46,pineMat,j===0?7:6);addMesh(tree,c,0,h*.42+j*h*.2,0)}const dust=cone(1.03,h*.44,snowMat,7);dust.scale.set(1,.32,1);addMesh(tree,dust,0,h*.62,0);scene.add(tree)}
// Craggy rocks and rune monoliths.
for(let i=0;i<27;i++){const a=Math.random()*Math.PI*2,r=13+Math.random()*52;const rock=addMesh(scene,new THREE.DodecahedronGeometry(.55+Math.random()*.75,0),Math.cos(a)*r,.3,Math.sin(a)*r);rock.material=i%4===0?iceMat:darkMat;rock.rotation.set(Math.random(),Math.random(),Math.random());rock.scale.y=.5+Math.random()*.7}
// Ember brazier at the heart of the ring.
const brazier=new THREE.Group();brazier.position.set(0,0,-1);scene.add(brazier);
const brazierBase=addMesh(brazier,new THREE.CylinderGeometry(.65,.82,.34,7),0,.28,0);brazierBase.material=darkMat;
for(let i=0;i<4;i++){const leg=addMesh(brazier,new THREE.BoxGeometry(.12,.75,.14),Math.cos(i*Math.PI/2)*.55,.55,Math.sin(i*Math.PI/2)*.55);leg.rotation.z=Math.cos(i*Math.PI/2)*-.2;leg.material=goldMat}
const fire=new THREE.Group();addMesh(brazier,cone(.45,1.25,new THREE.MeshBasicMaterial({color:0xff9a52}),6),0,1.16,0);addMesh(brazier,cone(.26,.9,new THREE.MeshBasicMaterial({color:0xffe3a1}),6),0,1.27,0);
const fireLight=new THREE.PointLight(0xff9e58,16,15,2);fireLight.position.set(0,1.5,0);brazier.add(fireLight);
const emberGlow=new THREE.Mesh(new THREE.SphereGeometry(3,14,10),new THREE.MeshBasicMaterial({color:0xff994a,transparent:true,opacity:.07,depthWrite:false}));emberGlow.position.y=1.1;brazier.add(emberGlow);

// Hero: layered leather, fur mantle, iron helmet and an oversized hand-forged axe.
const player=new THREE.Group();scene.add(player);player.position.set(0,0,6);
const torso=addMesh(player,new THREE.CylinderGeometry(.43,.58,1.18,7),0,1.23,0);torso.material=furMat;
const chest=addMesh(player,new THREE.BoxGeometry(.86,.74,.34),0,1.42,-.01);chest.material=darkMat;
const mantle=addMesh(player,new THREE.SphereGeometry(.59,8,5),0,1.83,-.04);mantle.material=furMat;mantle.scale.set(1,.42,.8);
const head=addMesh(player,sphere(.34,skinMat,10),0,2.18,0);
const helm=addMesh(player,new THREE.SphereGeometry(.38,8,5,0,Math.PI*2,0,Math.PI*.56),0,2.34,0);helm.material=goldMat;
const nose=addMesh(player,new THREE.BoxGeometry(.1,.34,.1),0,2.12,-.31);nose.material=goldMat;
const leftArm=addMesh(player,new THREE.Group(),-.55,1.56,0);const armMesh=addMesh(leftArm,new THREE.CylinderGeometry(.14,.2,.65,6),0,-.18,0);armMesh.material=furMat;
const rightArm=addMesh(player,new THREE.Group(),.55,1.56,0);const arm2=addMesh(rightArm,new THREE.CylinderGeometry(.14,.2,.65,6),0,-.18,0);arm2.material=furMat;
const axe=new THREE.Group();axe.position.set(.03,-.57,-.03);rightArm.add(axe);const handle=addMesh(axe,new THREE.CylinderGeometry(.055,.075,1.45,6),0,-.25,0);handle.material=woodMat;handle.rotation.z=-.18;
const blade=addMesh(axe,new THREE.BoxGeometry(.53,.48,.12),.22,.28,0);blade.material=iceMat;blade.rotation.z=-.55;const edge=addMesh(axe,new THREE.ConeGeometry(.22,.38,4),.46,.06,0);edge.material=iceMat;edge.rotation.z=Math.PI/4;
const belt=addMesh(player,new THREE.TorusGeometry(.44,.07,5,9),0,.95,0);belt.rotation.x=Math.PI/2;belt.material=goldMat;
const legs=[];for(const x of [-.24,.24]){const leg=addMesh(player,new THREE.Group(),x,.7,0);const lm=addMesh(leg,new THREE.CylinderGeometry(.17,.22,.74,6),0,-.26,0);lm.material=darkMat;legs.push(leg)}
