player.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true}});

// Three lost runeshards, each suspended above a frozen plinth.
const shardSpots=[new THREE.Vector3(-15,0,-12),new THREE.Vector3(17,0,-15),new THREE.Vector3(16,0,16)];
const shards=[];
for(let i=0;i<3;i++){const pos=shardSpots[i];const base=addMesh(scene,new THREE.CylinderGeometry(.7,.9,.22,6),pos.x,.12,pos.z);base.material=darkMat;const crystal=new THREE.Group();crystal.position.set(pos.x,.95,pos.z);const gem=addMesh(crystal,new THREE.OctahedronGeometry(.68,0),0,0,0);gem.material=new THREE.MeshStandardMaterial({color:0x9feaff,emissive:0x46c9ff,emissiveIntensity:1.6,metalness:.18,roughness:.22});gem.rotation.z=.2;const halo=new THREE.Mesh(new THREE.TorusGeometry(1.05,.025,5,32),new THREE.MeshBasicMaterial({color:0x8feaff,transparent:true,opacity:.72}));halo.rotation.x=Math.PI/2;crystal.add(halo);const light=new THREE.PointLight(0x71dfff,3,7,2);crystal.add(light);scene.add(crystal);shards.push({group:crystal,base,gem,position:pos,collected:false})}

// Snowfall gives the far forest scale and depth.
const snowCount=950,snowGeo=new THREE.BufferGeometry(),snowPos=new Float32Array(snowCount*3),snowSpeeds=[];
for(let i=0;i<snowCount;i++){snowPos[i*3]=(Math.random()-.5)*95;snowPos[i*3+1]=Math.random()*30;snowPos[i*3+2]=(Math.random()-.5)*95;snowSpeeds.push(.6+Math.random()*1.7)}
snowGeo.setAttribute('position',new THREE.BufferAttribute(snowPos,3));const snow=new THREE.Points(snowGeo,new THREE.PointsMaterial({color:0xf0fbff,size:.075,transparent:true,opacity:.72,depthWrite:false}));scene.add(snow);

const enemies=[];let kills=0,health=100,fury=100,shardCount=0,elapsed=0,started=false,ended=false,attackTimer=0,spawnTimer=1.2,toastTimer=0;
const keys={};
function makeEnemy(x,z){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);
 const body=addMesh(g,new THREE.CylinderGeometry(.43,.58,1.3,7),0,1.05,0);body.material=enemyMat;
 const head=addMesh(g,sphere(.37,enemyDark,8),0,1.98,-.02);
 const hood=addMesh(g,new THREE.SphereGeometry(.43,8,5,0,Math.PI*2,0,Math.PI*.62),0,2.1,0);hood.material=darkMat;
 const eyeMat=new THREE.MeshBasicMaterial({color:0x9dffbd});for(const x0 of [-.14,.14]){const e=addMesh(g,sphere(.055,eyeMat,6),x0,1.99,-.34);e.scale.set(1,.7,.5)}
 for(const x0 of [-.52,.52]){const a=addMesh(g,new THREE.CylinderGeometry(.14,.2,.7,6),x0,1.08,0);a.material=enemyDark;a.rotation.z=x0*.45}
 const healthBg=addMesh(g,new THREE.BoxGeometry(.8,.07,.04),0,2.62,0);healthBg.material=new THREE.MeshBasicMaterial({color:0x18272a});
 const healthFg=addMesh(g,new THREE.BoxGeometry(.75,.045,.045),0,2.63,-.03);healthFg.material=new THREE.MeshBasicMaterial({color:0xe69d82});
 const shadow=addMesh(g,new THREE.CircleGeometry(.65,12),0,.015,0);shadow.rotation.x=-Math.PI/2;shadow.material=new THREE.MeshBasicMaterial({color:0x172b32,transparent:true,opacity:.28,depthWrite:false});
 const enemy={group:g,hp:3,maxHp:3,attack:0,walk:Math.random()*8,healthFg,body,dead:false};enemies.push(enemy);return enemy}
function spawnEnemy(){if(kills+enemies.length>=12)return;const a=Math.random()*Math.PI*2,r=19+Math.random()*7;makeEnemy(player.position.x+Math.cos(a)*r,player.position.z+Math.sin(a)*r)}
function showToast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');toastTimer=2.2}
function updateHUD(){document.querySelector('#healthNum').textContent=Math.ceil(health);document.querySelector('#healthBar').style.width=Math.max(0,health)+'%';document.querySelector('#furyNum').textContent=Math.ceil(fury);document.querySelector('#furyBar').style.width=Math.max(0,fury)+'%';document.querySelector('#shardCount').textContent=`${shardCount} / 3`;document.querySelector('#enemyCount').textContent=enemies.filter(e=>!e.dead).length;document.querySelector('#timer').textContent=`${String(Math.floor(elapsed/60)).padStart(2,'0')}:${String(Math.floor(elapsed%60)).padStart(2,'0')}`;document.querySelector('#objective').textContent=shardCount<3?`Recover the runeshards · ${shardCount} of 3`:`Slay the draugr · ${kills} of 8`}
function endGame(won){if(ended)return;ended=true;document.querySelector('#endTitle').textContent=won?'REBORN':'FROSTFALL';document.querySelector('#endText').textContent=won?`The old world remembers you. ${String(Math.floor(elapsed/60)).padStart(2,'0')}:${String(Math.floor(elapsed%60)).padStart(2,'0')} · ${kills} draugr fallen.`:'The frost takes all things. But not your name.';document.querySelector('#endCard').classList.add('show');document.exitPointerLock?.()}
