const clock=new THREE.Clock(),cameraOffset=new THREE.Vector3(0,16.5,20),tempV=new THREE.Vector3();
function update(dt){
 // The world remains alive on the title screen, but the saga clock begins at entry.
 const t=clock.elapsedTime;fire.scale.setScalar(.92+Math.sin(t*12)*.08);fireLight.intensity=14+Math.sin(t*17)*3;emberGlow.material.opacity=.055+Math.sin(t*8)*.02;
 for(const s of shards){if(s.collected)continue;s.group.position.y=.95+Math.sin(t*2.2+s.position.x)*.18;s.group.rotation.y+=dt*.42;s.gem.rotation.x+=dt*.4;}
 const positions=snow.geometry.attributes.position.array;for(let i=0;i<snowCount;i++){positions[i*3+1]-=snowSpeeds[i]*dt;positions[i*3]+=.12*dt;if(positions[i*3+1]<0){positions[i*3+1]=30;positions[i*3]=player.position.x+(Math.random()-.5)*95;positions[i*3+2]=player.position.z+(Math.random()-.5)*95}}snow.geometry.attributes.position.needsUpdate=true;snow.position.set(player.position.x,0,player.position.z);
 if(started&&!ended){elapsed+=dt;fury=Math.min(100,fury+(keys.ShiftLeft||keys.ShiftRight?3:11)*dt);if(attackTimer>0){attackTimer-=dt;if(attackTimer<.39){rightArm.rotation.x=THREE.MathUtils.lerp(rightArm.rotation.x,0,dt*11);rightArm.rotation.z=THREE.MathUtils.lerp(rightArm.rotation.z,0,dt*11)}}
  let mx=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0),mz=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0);const len=Math.hypot(mx,mz);if(len){mx/=len;mz/=len;const sprint=(keys.ShiftLeft||keys.ShiftRight)&&fury>2;const speed=sprint?9:5.7;if(sprint)fury=Math.max(0,fury-15*dt);player.position.x+=mx*speed*dt;player.position.z+=mz*speed*dt;const yaw=Math.atan2(-mx,-mz);player.rotation.y=THREE.MathUtils.lerp(player.rotation.y,yaw,Math.min(1,dt*9));legs[0].rotation.x=Math.sin(t*12)*.48;legs[1].rotation.x=-Math.sin(t*12)*.48}else{legs[0].rotation.x=THREE.MathUtils.lerp(legs[0].rotation.x,0,dt*8);legs[1].rotation.x=THREE.MathUtils.lerp(legs[1].rotation.x,0,dt*8)}
  const radius=Math.hypot(player.position.x,player.position.z);if(radius>68){player.position.x*=68/radius;player.position.z*=68/radius}
  for(const s of shards){if(!s.collected&&player.position.distanceTo(new THREE.Vector3(s.position.x,0,s.position.z))<2.1){s.collected=true;s.group.visible=false;s.base.visible=false;shardCount++;fury=Math.min(100,fury+25);showToast('RUNESHARD CLAIMED · +25 FURY');if(shardCount===3)showToast('THE LAST EMBER AWAKENS');}}
  spawnTimer-=dt;const living=enemies.filter(e=>!e.dead).length;if(spawnTimer<=0&&living<4&&kills+living<12){spawnEnemy();spawnTimer=3.1+Math.random()*1.8}
  for(const e of enemies){if(e.dead)continue;const dx=player.position.x-e.group.position.x,dz=player.position.z-e.group.position.z,d=Math.hypot(dx,dz);e.walk+=dt*5;if(d>1.55){e.group.position.x+=(dx/(d||1))*1.55*dt;e.group.position.z+=(dz/(d||1))*1.55*dt;e.group.rotation.y=Math.atan2(-dx,-dz);e.group.position.y=Math.abs(Math.sin(e.walk))*.055}else{e.attack-=dt;if(e.attack<=0){e.attack=1.35;if(d<1.7){health=Math.max(0,health-9);showToast('THE DRAUGR STRIKES');if(health<=0)endGame(false)}}}e.group.position.y+=Math.sin(e.walk)*.002;e.body.rotation.z=Math.sin(e.walk)*.035}
  if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)document.querySelector('#toast').classList.remove('show')}
  if(shardCount>=3&&kills>=8)endGame(true);updateHUD();
 }
 const target=new THREE.Vector3(player.position.x+cameraOffset.x,player.position.y+cameraOffset.y,player.position.z+cameraOffset.z);camera.position.lerp(target,.075);camera.lookAt(player.position.x,1.1,player.position.z-1.6);renderer.render(scene,camera)
}
function frame(){requestAnimationFrame(frame);update(Math.min(clock.getDelta(),.05))}frame();
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))});
</script>
